// The Cloudflare Worker's entry point: the Next.js app (built by OpenNext) for web requests,
// plus the 5-minute schedule that runs the background jobs (see packages/core/src/monitoring).
import {
  createMonnifyGatewayFromEnv,
  createProviderRegistry,
  jobsDueAt,
  runJobs,
} from "@repo/core";
import { createDb } from "@repo/db";

// Generated by `opennextjs-cloudflare build`, so it only exists after a build. Ignoring the type
// check here (rather than expecting an error) keeps typecheck passing before and after a build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as nextHandler } from "./.open-next/worker.js";

interface Env {
  HYPERDRIVE: { connectionString: string };
  [name: string]: unknown;
}

/** Strings from the Worker's settings and secrets, for the code that reads them like env vars. */
function stringVars(env: Env): Record<string, string | undefined> {
  const out: Record<string, string | undefined> = {};
  for (const [key, value] of Object.entries(env)) if (typeof value === "string") out[key] = value;
  return out;
}

const worker = {
  fetch: nextHandler.fetch,

  async scheduled(event: { scheduledTime: number }, env: Env): Promise<void> {
    const vars = stringVars(env);
    const { db, close } = createDb(env.HYPERDRIVE.connectionString, {
      maxConnections: 2,
      maxUses: 1,
    });
    try {
      const results = await runJobs({
        db,
        getProvider: createProviderRegistry(vars),
        getFundingGateway: () => createMonnifyGatewayFromEnv(vars),
        only: jobsDueAt(new Date(event.scheduledTime)),
      });
      for (const r of results) {
        console.log(`job ${r.job}: ${r.ok ? "ok" : `failed: ${r.error}`}`, r.summary ?? "");
      }
    } finally {
      await close();
    }
  },
};

export default worker;
